INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('fa2bb4c1-7cd7-462c-a2e3-3063c54b7279', '20000000-0000-0000-0000-000000000001', 'Áo Sơ Mi Thanh Lịch Boxy Oxford — Trắng kem', 1190000, 'Áo Sơ Mi Thanh Lịch Boxy Oxford — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Made of soft, premium organic cotton, the Boxy Oxford features a classic point collar, dropped shoulders, a clean button front, oversized patch pockets, and of course, relaxed boxy shape. Polish it up with trousers and heels, or dress it down with jeans and sneakers for a casual-yet-put-together look. Either way, you’ll look like you know what you’re doing. Buy a few, we won’t judge.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 28, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/F-BTDN-CTN-OOXF-BF-WHT_0038.jpg?v=1784064032&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/50e68f27_18b2.jpg?v=1753411392&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


