INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('7861dcb5-d241-4e38-af21-303cf8ce90fc', '20000000-0000-0000-0000-000000000001', 'Áo Sơ Mi Thanh Lịch Way-Short Shirt in Silky Cotton — Trắng kem', 2750000, 'Áo Sơ Mi Thanh Lịch Way-Short Shirt in Silky Cotton — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Made from high-twist, 100% cotton yarn in a soft twill weave, the Way-Short Shirt in Silky Cotton features a point collar, a clean button front, one patch pocket, and a cropped shape that pairs perfectly with high-waisted bottoms. Wear it with jeans for a classic look, or pair it with something stretchy for an easy (yet super-flattering) outfit.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 47, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/a5df2a6b_1275.jpg?v=1753411468&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/23721712_6048.jpg?v=1753411468&width=900')
