INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('75ba132e-6832-48ac-ae75-63cd4b5593e7', '20000000-0000-0000-0000-000000000002', 'Quần Âu Ống Suông Utility Barrel Pant — Đen', 3810000, 'Quần Âu Ống Suông Utility Barrel Pant — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. To quote you—our customers, there’s really no competition, the Utility Barrel Pant really is that good. Made of medium-weight cotton twill with just a touch of stretch, it features a high rise to hold you in, and that main-character-energy curved leg in an easy cropped length. Cool utilitarian paneling and butt-boosting patch pockets give you legs for days without all the hours of Pilates. Consider these your ultimate antidote to living in jeans.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 151, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2022-03-20_F-BTM-CTN-BAREL-UTL-OBLK_01_9d599c8d-5fd4-472f-b235-8d176dc1a85a.jpg?v=1789794378&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/9cb8da52_1b75.jpg?v=1753411410&width=900')
