INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('eabdcc6a-0886-4bc1-aa2f-ee604b13ca21', '20000000-0000-0000-0000-000000000002', 'Quần Âu Ống Suông Organic Straight-Leg Pant — Đen', 3330000, 'Quần Âu Ống Suông Organic Straight-Leg Pant — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. The Organic Straight-Leg Pant is back and better than ever. Featuring the same waist-nipping, butt-boosting, and leg-lengthening look you love from the original Straight-Leg Crop Pant—now in organic twill. Soft is an understatement. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 227, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/8644d351_5344.jpg?v=1753411575&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/18c4f697_504b.jpg?v=1753411575&width=900')
