INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('9a29ead4-a06e-4b1e-a033-ab93cd02b2e9', '20000000-0000-0000-0000-000000000002', 'Quần Âu Ống Suông Chino in Buttersoft — Đen', 2490000, 'Quần Âu Ống Suông Chino in Buttersoft — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Our Chino in Buttersoft is a high-waisted pant crafted in a buttery soft, 100% TENCEL™ Lyocell fabric. It features a cool curved leg (similar to the Utility Barrel Pant) and asymmetrical back pockets: one with a button-back flap pocket and one with a slip pocket. These pants are slouchy, so if you want a slimmer fit, try sizing down.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 246, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/aaba4ae6_66f5.jpg?v=1753411475&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/f871066d_99d8.jpg?v=1753411475&width=900')
