INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('671eb09b-7e14-4380-ae44-cb041db15990', '20000000-0000-0000-0000-000000000002', 'Quần Short Tinh Gọn Perform Bike Short — Đen', 2130000, 'Quần Short Tinh Gọn Perform Bike Short — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Made of premium performance fabric from a renowned Italian mill, the Perform Bike Short features an extra-high waist, minimal seams, an interior pocket, and lightweight compression with technical sweat-wicking properties. Plus, it’s comprised of 58% recycled nylon. We’ve eliminated 90% of the virgin plastic from our supply chain. Learn about what we’ve done—and the challenges ahead—on our Sustainability page. Looking for more Perform items? Browse the collection and make it a set.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 265, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/086dc0c9_2a06.jpg?v=1753411396&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2906cbfe_74dd.jpg?v=1753411395&width=900')
