INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('0c10c5ad-f5d2-4c8a-a8da-62eec0c7ef46', '20000000-0000-0000-0000-000000000002', 'Quần Perform Pocket Legging — Đen', 2850000, 'Quần Perform Pocket Legging — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. The Perform Pocket Legging is made of the same premium performance fabric as our best-selling legging—with lightweight compression and sweat-wicking properties—and features the same extra-high waist and versatile look. What sets it apart? Leg-lengthening seams and pockets that are perfect for stashing essentials. And just like everything in our Perform collection, it’s comprised of 58% recycled nylon. Looking for more Perform items? Browse the collection and make it a set. We’ve eliminated 90% of the virgin plastic from our supply chain. Learn about what we’ve done—and the challenges ahead—on our Sustainability page.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 215, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/e29dc978_13f4.jpg?v=1750093688&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/3dbf53d7_ff45.jpg?v=1750093688&width=900')
