INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('8759a5bc-b340-4dae-a4bb-d51608bb0906', '20000000-0000-0000-0000-000000000002', 'Quần Track Jogger — Đen', 1530000, 'Quần Track Jogger — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Featuring an elastic waistband, an easy high rise, handy side pockets, and a relaxed tapered leg, the Track Jogger has a signature look that will stand the test of time. Plus, it’s made of custom-developed, organic french terry, which gives it a premium feel without the luxury markup. Like everything in our Track collection, this sweatpant is certified organic by the Global Organic Textile Standard (GOTS). This certification takes over a year to account for every step of production—from the processing of certified organic fiber into yarn to the dyehouses, mills, factories, and printers. Looking for more Track styles? Shop the collection and make it a set.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 234, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/0698df7f_492f.jpg?v=1750093642&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/8cade37c_a304.jpg?v=1750093642&width=900')
