INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('e1c2767c-01dd-4b7a-acb1-3859f852e645', '20000000-0000-0000-0000-000000000002', 'Quần Short Tinh Gọn Retro Jersey Short — Đen', 2970000, 'Quần Short Tinh Gọn Retro Jersey Short — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Reminiscent of ’70s summer camp threads, the Retro Jersey Short features an easy elastic waist, an extra-high rise, handy side pockets, a back patch pocket, a 3.5" inseam, and a relaxed fit. Plus, it’s made of 100% organic jersey that’s light, breathable, and perfect for warm-weather days. This product is certified organic to the Global Organic Textile Standard (GOTS) standard. The GOTS certification process takes over a year to complete and accounts for every step of production—from the processing of certified organic fiber into yarn, to the dyehouses, mills, factories, and printers. We are audited annually to verify traceability throughout our entire supply chain—ensuring that our GOTS-certified products pass all ecological and social standards from seed to finished garment. Looking for more Retro Jersey styles? Shop the collection and make it a set.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 70, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/0c9ab05d_a4ac.jpg?v=1750093704&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/87ebdda4_7100.jpg?v=1750093704&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


