INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('582bde28-c7c6-490e-a736-0ee1deb295f1', '20000000-0000-0000-0000-000000000002', 'Quần Âu Ống Suông Linen Pull-On Barrel Pant — Đen', 3690000, 'Quần Âu Ống Suông Linen Pull-On Barrel Pant — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. We combined our soft, breathable linen fabric with the beloved, craftsman-inspired shape of our Utility Barrel Pant. The Linen Utility Barrel Pant is made of 100% linen, featuring an elasticated waist with drawcord, front angled pockets, and a relaxed, curved leg. Look cool, stay cool—perfect for lazy days when you want to look put together.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 46, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/6fe10803_f6e6.jpg?v=1753411642&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/5a519176_5b74.jpg?v=1753411642&width=900')
