INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('89780985-0275-4d63-a4f5-1381045fab22', '20000000-0000-0000-0000-000000000002', 'Quần Âu Ống Suông Corduroy Gardener Pant — Xanh dương', 2970000, 'Quần Âu Ống Suông Corduroy Gardener Pant — Xanh dương với sắc xanh dương tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. If you love the Gardener Jean you’ll be an instant fan of the Corduroy Gardener Pant. Taking the same high-rise silhouette as the jean version, these wide-leg pants feature extra large functional pockets that wrap around from front to back, utility style stitching, a zipper fly, and a cropped length. Oh, and did we mention, it’s made with our velvety-soft corduroy, for an elevated edge.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 84, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/01573bc7_ecf2.jpg?v=1753411643&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/5f7c5f90_bbc4.jpg?v=1753411642&width=900')
