INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('d9756432-7264-4dba-a887-12f670483482', '20000000-0000-0000-0000-000000000002', 'Quần Âu Ống Suông City Stripe Way-High® Drape Pant — Đen', 2610000, 'Quần Âu Ống Suông City Stripe Way-High® Drape Pant — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. The City Stripe Way-High® Drape Pant has the same great fit as the OG—including that extra-high rise, flattering front pleats, front and back welt pockets, plus hidden zipper, but is now served in a light drapey, textured FSC-certified viscose and REPREVE® recycled polyester blend. A more low-key put-together look, add it to your City Stripe collection or pair with other pieces for a little high-low love. This fabric has a heavier weight and is great for transitioning seasons. Made from post-consumer plastic bottles that are collected, washed, chopped, melted, and then made into polyester yarn, REPREVE® recycled polyester boasts less energy and water usage as well as reduced greenhouse gas emissions, when compared to virgin polyester and other conventional recycled plastic sources. The REPREVE® registration platform provides full supply chain visibility from source to product—ensuring the exact bottle count per product and source location of those bottles. To date, REPREVE® has saved over 30 billion plastic bottles from landfill.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 103, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/c29d1d2e_2edb.jpg?v=1753411573&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/554294f9_994a.jpg?v=1753411572&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


