INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('c360c429-bf9d-4518-a87b-37faf42b187f', '20000000-0000-0000-0000-000000000003', 'Quần Jeans Cạp Cao Supersoft Jean Coverall — Xanh dương', 2450000, 'Quần Jeans Cạp Cao Supersoft Jean Coverall — Xanh dương với sắc xanh dương tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. The Slouch Summer Jean Coverall is a short-sleeve, full-length denim jumpsuit with a cool utility vibe. Featuring a button-down collar, double top flap pockets plus side slash pockets, belt loops help accent the waistband. Made of 60% organic cotton and 40% TENCELTM Lyocell with REFIBRATM technology for a soft, relaxed denim look. Produced using 95% less water than conventional cotton production, TENCELTM with RefibraTM technology is a 100% bio-based man-made cellulosic (MMC) material that uses both upcycled cotton textiles (up to 33%) as well as FSC-certified, sustainably sourced wood pulp to create a partly renewed version of Tencel™ Lyocell that contributes to the circular economy.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 174, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/a5056d89_a839.jpg?v=1753411493&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/d464a322_5e09.jpg?v=1753411493&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


