INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('73d8ff67-1915-41f0-a23e-98f8e3a5a1bf', '20000000-0000-0000-0000-000000000003', 'Váy Wrap Jumpsuit in Linen — Đen', 1850000, 'Váy Wrap Jumpsuit in Linen — Đen với sắc đen tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. Making dressing decisions easy, meet The Linen Cross Front Jumpsuit. Its relaxed silhouette features a cool cross-front effect, wide elbow-length sleeves, angled front pockets, and a removable linen belt for optional added waist definition. Low-key culotte style legs hit mid calf. Made with cool, crisp linen to keep things oh-so chill. This jumpsuit is designed to fit oversized. For a more true to size fit, we recommend sizing down.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 231, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/49d3a180_be06.jpg?v=1753411659&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/4d6e40e8_945d.jpg?v=1753411658&width=900')
