INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('566051bf-c262-4183-af23-3bf3793ef194', '20000000-0000-0000-0000-000000000003', 'Đầm Thiết Kế Tôn Dáng Easy Workwear Dress — Trắng kem', 3410000, 'Đầm Thiết Kế Tôn Dáng Easy Workwear Dress — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. Featuring patch and on-seam pockets, center front placket with hidden button closure, stand collar, and slits at the hem. The best part? It’s made with 98% organic cotton. This dress is designed to be oversized. For a smaller fit, we recommend sizing down. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 250, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/d3a1420e_eb24.jpg?v=1753411516&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/d61b92ef_2c58.jpg?v=1753411516&width=900')
