INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('e0dc84b6-8c3f-4273-a275-fa4cc93263ed', '20000000-0000-0000-0000-000000000003', 'Đầm Thiết Kế Tôn Dáng Long-Sleeve Riviera Dress — Đen', 3770000, 'Đầm Thiết Kế Tôn Dáng Long-Sleeve Riviera Dress — Đen với sắc đen tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. Made from a stretchy Supima® cotton jersey, The Riviera Dress features a comfortable long-sleeve knit top with a rounded scoop neck and a voluminous woven bottom. The top portion is made from our ultra-soft and durable Supima® cotton, while the skirt is made with 100% cotton for all-day breathability. The pinnacle of versatility. Did we mention it has pockets? Grown in the United States, Supima® cotton is distinguished by its extra-long fiber length, which gives it more durability and a softer hand feel. Supima® is able to authenticate the source of its cotton across the entire supply chain, from the fiber and yarn to the fabric and finished product.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 181, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/3ad71a73_9470.jpg?v=1753411697&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/cc953fd6_2ac2.jpg?v=1753411698&width=900')
