INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('baed8cf7-af40-4cd1-abbc-dbcd782154d5', '20000000-0000-0000-0000-000000000003', 'Áo Dệt Kim Thu Đông Cozy Stretch Turtleneck Dress — Xanh dương', 1970000, 'Áo Dệt Kim Thu Đông Cozy Stretch Turtleneck Dress — Xanh dương với sắc xanh dương tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. Made from a soft blend of responsibly sourced wool, yak, and recycled nylon with a touch of spandex, The Cozy Stretch Turtleneck Dress lives up to its name. Featuring an elevated neckline, relaxed fit, and ribbed detailing, this slip-on silhouette delivers high amounts of comfort and style. Pair with our Italian Leather Day Ballet Flat for a simple, yet sophisticated, look. The wool in this sweater is certified by the Responsible Wool Standard, which ensures the welfare of the sheep and the land they graze on.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 238, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/7bdc77c8_76fc.jpg?v=1753411416&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2978eb44_77d0.jpg?v=1753411416&width=900')
