INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('fe98205f-7d21-4632-ae40-069db4828a43', '20000000-0000-0000-0000-000000000003', 'Váy Canvas Organic Cotton Coverall — Trắng kem', 2090000, 'Váy Canvas Organic Cotton Coverall — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. Salt baked for its crinkled texture (hence the name), The Crinkled Organic Cotton Coverall is a long-sleeve, full-length, 100% organic cotton jumpsuit with a cool and comfortable utility vibe. Featuring a button-front, elastic waist and an oversized fit with adjustable cuffs. We’re jumping into this even on our days off—looking good is hard work after all. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 169, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/3ecbe759_7db4.jpg?v=1753411604&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/d20366c9_6318.jpg?v=1753411604&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


