INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('2032ee0e-1905-45f4-a9be-46d28b32ca14', '20000000-0000-0000-0000-000000000003', 'Đầm Thiết Kế Tôn Dáng City Stripe Midi Dress — Đen', 3770000, 'Đầm Thiết Kế Tôn Dáng City Stripe Midi Dress — Đen với sắc đen tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. Low-key vibes in a high-key silhouette, meet The City Stripe Midi Dress. This relaxed midi-length bias-cut slip dress features a deep, flattering V-neckline at both the front and back, in chic stripes for added impact. Made with 66% Viscose and 34% REPREVE® recycled polyester. Wear solo or layer up with jackets, cardigans, or shirts for all year round style. The viscose in this garment comes from an FSC-certified supplier who has been audited and assessed as being at low risk, or has taken substantive action to eliminate known risk of sourcing rayon and viscose from ancient and endangered forests by CanopyStyle. Made from post-consumer plastic bottles that are collected, washed, chopped, melted, and then made into polyester yarn, REPREVE® recycled polyester boasts less energy and water usage as well as reduced greenhouse gas emissions, when compared to virgin polyester and other conventional recycled plastic sources. The REPREVE® registration platform provides full supply chain visibility from source to product—ensuring the exact bottle count per product and source location of those bottles. To date, REPREVE® has saved over 30 billion plastic bottles from landfill.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 245, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/07ee8bac_69ed.jpg?v=1753411599&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2dae2d3c_d924.jpg?v=1753411599&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


