INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('c525fbe4-60cb-4942-aff1-041a900d3191', '20000000-0000-0000-0000-000000000003', 'Váy Structured Cotton Jumpsuit — Xanh dương', 2570000, 'Váy Structured Cotton Jumpsuit — Xanh dương với sắc xanh dương tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. For your best silhouette yet, meet The Structured Cotton Jumpsuit. With its clean, streamlined structure, this sleeveless jumpsuit features a flattering V-neck, a lined top bodice for extra definition and comfort, a gently fitted waist, and straight, slim legs. Made with our new woven clean compact cotton fabric with slight stretch, it hugs and releases in all the right places.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 43, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/3710ffbf_e38d.jpg?v=1753411526&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/4b7ccd8e_cfbf.jpg?v=1753411526&width=900')
