INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('cadada91-3dec-4689-abf4-5f1361e09b2d', '20000000-0000-0000-0000-000000000003', 'Áo Lụa Mềm Mại Hammered Satin Slip Dress — Đen', 2930000, 'Áo Lụa Mềm Mại Hammered Satin Slip Dress — Đen với sắc đen tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. Whatever the occasion, this versatile Hammered Satin Slip Dress will see you through in style. A sleek and minimalist midi length silhouette, it features a scoop neck, spaghetti straps, and neat side slit. It’s made with our hammered satin effect viscose for that gentle shine and instant put-together polish. Dress up with heels and a blazer, or go low-key with sandals. Viscose is FSC-certified with Dark Green Shirt designation. The viscose in this garment comes from a Forest Stewardship Council (FSC)-certified supplier who was awarded a Dark Green Shirt designation by CanopyStyle, indicating that they have been audited and assessed as being at low risk, or has taken substantive action to eliminate known risk of sourcing rayon and viscose from Ancient and Endangered Forests. FSC standards also expand protection of water quality, ban highly hazardous chemicals, and require forest managers to engage local community members as well as protect customary rights of indigenous people.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 62, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/fc647e23_3928.jpg?v=1753411628&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/05c359e8_5de6.jpg?v=1753411628&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


