INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('404016c0-fe16-429a-a4d4-fc2b97ecafb9', '20000000-0000-0000-0000-000000000003', 'Đầm Thiết Kế Tôn Dáng Seersucker Puff Sleeve Dress — Trắng kem', 3290000, 'Đầm Thiết Kế Tôn Dáng Seersucker Puff Sleeve Dress — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác tôn vòng eo và kéo dài tỷ lệ cơ thể cho cả công sở lẫn tiệc tối sang trọng. For a more directional sleeve detail, meet The Seersucker Puff Sleeve Dress. The perfect combination of gathered neckline, ultra puffy sleeves—nipped in at the hem, plus large front pockets, it’s both playful and pragmatic. Made of organic seersucker cotton, it hits just above the knee in an A-line silhouette. A dress that demands to fly solo, style it with mules or sneakers depending on your mood.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 81, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/af3093be_5f15.jpg?v=1750093821&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/633d0ccf_7bf0.jpg?v=1750093821&width=900')
