INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('698dd653-f52f-40b6-afeb-1b059cf915c2', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Short Anorak — Xanh rêu', 3010000, 'Áo Khoác Cấu Trúc Short Anorak — Xanh rêu với sắc xanh rêu tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. An all-season essential ready to launch in your feed, we took your favorite anorak silhouette and gave it a shorter new look. Featuring a removable hood, front flap pockets, and snap and zipper front closures, there’s a back vent to keep you fresh. Plus it''s both water resistant and repellant. Lightweight for layering and keeping the weather out, it''s an off-duty essential, ready for anything from bagel runs to brunch.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 38, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/657dd475_03b4.jpg?v=1770141604&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2025-02-02_F-OTWR-PKA-ANRK-ST-TRNCH_flat.jpg?v=1782318853&width=900')
