INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('d25738ca-9845-4082-a8a7-75ee826a47cc', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Italian ReWool® Cocoon Coat — Đen', 2650000, 'Áo Khoác Cấu Trúc Italian ReWool® Cocoon Coat — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Exceptionally soft and durable, The ReWool Cocoon Coat is made of premium recycled wool from our partner mill in Italy. With a classic notch collar, dropped shoulders, three-button front closure, and welt pockets. The best part? We’re taking recycling to a whole new level—featuring recycled trims including buttons and lining, so you can love, enjoy, and pass it on for years to come. We’re giving wool a second life. Every year thousands of premium wool garments end up in landfills (shocking, we know)—but our partner mills in Italy are changing that. They collect, renew, and reuse these along with blended nylon to create our beautiful and durable ReWool fabric. Using recycled wool fibers lowers our raw material carbon emissions by over 90% compared to virgin wool.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 57, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2d3c78a6_c2d7.jpg?v=1753411500&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/57dfb0a4_fafe.jpg?v=1753411500&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


