INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('baa25b4b-87b9-4f31-a7d3-815accb151da', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Long Re:Down® Puffer — Đen', 3610000, 'Áo Khoác Cấu Trúc Long Re:Down® Puffer — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. The Re:Down® Puffer is a mid-length hooded jacket featuring a center-front two-way zipper with double zipper pulls, plus on-seam pockets with internal snap closures. It has internal drawstrings at the hem and hood to help adjust the fit. Puffed-up for warmth, it’s filled with recycled down feathers, while the jacket is made with our recycled GRS-certified and bluesign approved nylon and lined with recycled polyester. Re:Down® repurposes feathers and down from pillows, comforters, and sleeping bags to give you luxurious softness that’s 100% warm, 100% natural, and 100% recycled. With the goal of increasing the use of recycled materials and reducing the harmful impacts of production, the Global Recycled Standard (GRS) sets requirements for third-party certification of recycled input in products—including chain of custody, social and environmental practices, and chemical restrictions.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 95, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/04b8ebed_aed3.jpg?v=1753411662&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/ac8ce47f_1c65.jpg?v=1753411662&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


