INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('025a9966-a7a1-4ff1-a099-8ec1f410e444', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Canvas Organic Cotton Anorak — Trắng kem', 4570000, 'Áo Khoác Cấu Trúc Canvas Organic Cotton Anorak — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Part of our Canvas Collection of modern workwear, the Canvas Organic Cotton Anorak is a military-inspired jacket made with heavyweight, 100% OCS-certified organic cotton. To give it a unique and subtle texture that withstands the test of time, we followed a centuries-old, Japanese salt shrinking process and then garment dyed it. Due to the natural effects of garment dyeing, you’ll find each piece in the collection is slightly different, creating a soft, vintage look. Detailed with a spacious hood, zip front, foldable sleeves, and large patch pockets with a top and side entry, we love pairing this sturdy staple with the Way-High Sailor Jean. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 209, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/659c27fb_3631.jpg?v=1753411613&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/fc659abe_c66f.jpg?v=1753411613&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
