INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('d2d32472-0eb3-4728-a0f4-692db06b02e5', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Drapey Blazer — Đen', 2650000, 'Áo Khoác Cấu Trúc Drapey Blazer — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Taking those oh-so cool-girl relaxed vibes of the Japanese GoWeave Drapey Blazer and remixing it in FSC-certified triacetate, this blazer is the ultimate throw-on-and-go topper. It features a double-breasted silhouette with notch collar and lapels, softly tailored shoulders—with internal shoulder pads, and front welt pockets. Pair it with the Triacetate Way-High® Drape Pant for a head-to-toe party look. The Forest Stewardship Council (FSC) certification ensures that products come from responsibly managed forests. The standards expand the protection of water quality, prohibit harvest of rare old-growth forests, ban highly hazardous chemicals, and require forest managers to engage local community members as well as protect customary rights of indigenous people.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 45, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/51488977_cb9a.jpg?v=1753411602&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/345cb211_d481.jpg?v=1753411602&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


