INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('bacda1fe-9aa1-4f58-acb3-91f5fbf6b617', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Canvas Organic Cotton Parka — Trắng kem', 3970000, 'Áo Khoác Cấu Trúc Canvas Organic Cotton Parka — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Part of our Canvas Collection of modern workwear, the Canvas Cotton Organic Parka features a removable hood, front zipper, recycled metal button closure, cinchable waist, and deep welt pockets. To create a subtle texture in the heavyweight, 100% OCS-certified organic cotton fabric, we followed a centuries-old, Japanese salt shrinking process and then garment dyed it. Due to the natural effects of garment dyeing, you’ll find each piece in the collection is slightly different, creating a soft, vintage look. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 64, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/ea22aab8_79ed.jpg?v=1753411607&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/b0f6a8f9_1ad4.jpg?v=1753411607&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


