INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('65b7eaa4-e935-4a5a-ac26-3a8ddb712405', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Field Jacket — Đen', 4690000, 'Áo Khoác Cấu Trúc Field Jacket — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. This utilitarian-style field jacket has practical features built-in—including a full zip with snap placket and internal hidden drawstring for adjustable waist definition. Hitting at mid thigh, it has four patch pockets with flaps and hidden snaps, plus snap-adjustable cuffs. Made with 100% certified organic cotton, it has a PFAs-free water resistant and repellent finish. Here to do all the heavy-lifting, wear it with jeans for utilitarian vibes or dress up with a wide-leg trouser.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 102, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/d0ed0ccd_8d06.jpg?v=1756435565&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/6ed492e9_2ece.jpg?v=1756435563&width=900')
