INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('9c2c012c-2c20-4335-ae7e-663162f94a76', '20000000-0000-0000-0000-000000000004', 'Áo Sơ Mi Thanh Lịch Italian ReWool® Oversized Shirt Jacket — Trắng kem', 4330000, 'Áo Sơ Mi Thanh Lịch Italian ReWool® Oversized Shirt Jacket — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Part shirt, part jacket, all style, the versatile Italian ReWool® Oversized Shirt Jacket will be your new styling go-to. It features classic shirt detailing including a collar, cuffs with buttons, and shirttail hem, along with two front chest flap pockets and on-seam pockets. The sleeves are lined for added warmth and it’s made with a GRS-certified recycled Italian wool and GRS-certified recycled nylon blend. Think cozy, comfy, and it literally goes with everything. With the goal of increasing the use of recycled materials and reducing the harmful impacts of production, the Global Recycled Standard (GRS) sets requirements for third-party certification of recycled input in products—including chain of custody, social and environmental practices, and chemical restrictions.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 235, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/cc7a4be7_f32f.jpg?v=1753411652&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/66559e4d_6605.jpg?v=1753411652&width=900')
