INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('1daabcf0-f7a7-4dd0-a5f8-8178ae563580', '20000000-0000-0000-0000-000000000004', 'Áo khoác ReNew Quilted Hooded Liner — Đen', 3010000, 'Áo khoác ReNew Quilted Hooded Liner — Đen với sắc đen tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Versatile and lightweight, this water repellent and resistant onion-quilted puffer features an adjustable drawstring hood and dipped shirttail hem. Patch pockets with top and side entry keep things practical. Made from our 100% recycled bluesign®-certified polyester, with recycled fill from Primaloft®. A multi-tasking transitional jacket, wear it solo ''til the temps drop, then layer under your coat for added cozy.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 254, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/a2fbfa5e_2168.jpg?v=1756867653&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/0d150f4d_2059.jpg?v=1756867653&width=900')
