INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('a30e46a8-9ac4-4b14-a68c-893b68564255', '20000000-0000-0000-0000-000000000004', 'Áo khoác ReNew Fleece Full Zip — Nâu Caramel', 3610000, 'Áo khoác ReNew Fleece Full Zip — Nâu Caramel với sắc nâu caramel tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Say hello to our new shearling-inspired fleece zip up. It features a slightly oversized fit with a high neck—to keep the cold breeze at bay. It has zippered pockets and detailed binding on the edges. This sweater will make staying cute and cozy this season a simple feat. Plus, It’s made from 100% GRS-certified recycled polyester* and thoughtfully with bluesign®-approved dyes—which are safer for dyehouse workers and better for the environment, compared to traditional dye methods. *Some of the trim isn’t 100% recycled, but we’re working on it.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 33, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/ad42e2aa_c274.jpg?v=1753411597&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/136b68af_90c3.jpg?v=1753411597&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


