INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('0757bede-4e8c-40ef-ae51-4e17a2ab95f0', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc Organic Cotton Herringbone Jacket — Trắng kem', 4690000, 'Áo Khoác Cấu Trúc Organic Cotton Herringbone Jacket — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Light on the body, heavy on the statement—featuring a relaxed fit, The Organic Cotton Herringbone Jacket is made of non-stretch, 100% organic cotton twill, has a double breasted button closure, utility twin needle topstitching, with welt and flap front pockets. Complete the look with the matching Organic Cotton Herringbone Pant or Organic Cotton Herringbone Dress. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 52, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/30490879_8672.jpg?v=1753411573&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/849b13d9_9a0c.jpg?v=1753411573&width=900')
