INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('975385f7-059e-4525-adac-45241a20b790', '20000000-0000-0000-0000-000000000004', 'Áo Khoác Cấu Trúc ReWool® Double-Breasted Blazer — Nâu Caramel', 4810000, 'Áo Khoác Cấu Trúc ReWool® Double-Breasted Blazer — Nâu Caramel với sắc nâu caramel tinh tế, đường cắt chuẩn xác phù hợp mặc đi làm công sở, gặp đối tác hoặc dạo phố thanh lịch. Made with our much-loved GRS-certified Italian recycled wool and GRS-certified recycled nylon blend, the ReWool® Double-Breasted Blazer has all the classic tailoring detailing you love—peak lapels, two front welt flap pockets, a front welt pocket on the chest, plus four buttons on each cuff. Fully lined and featuring internal shoulder pads to add shape, it gives a nod to heritage blazers while feeling modern and fresh. Our partner mill in Italy collects premium wool garments from recycling programs and gives them a second life by blending them with recycled nylon for extra durability. The end result? Our beautiful ReWool® fabric that, like fine wine, only gets better with age.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 71, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/e93a1d25_3aea.jpg?v=1753411601&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/01e7dc71_4a1c.jpg?v=1753411601&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


