INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('e931b3ef-88be-41ef-a860-464274b322ff', '20000000-0000-0000-0000-000000000007', 'Giày Bệt & Loafer Da Mềm Modern Loafer — Đen', 3830000, 'Giày Bệt & Loafer Da Mềm Modern Loafer — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Made from buttery-soft leather, this 2.0 take features a sleek tapered toe, stitch detailing, and a slightly thicker stacked heel. Plus, we’ve added additional padding and a foam-cushioned insole, so there’s zero break-in needed for your first wear. Dress it up with a trench and trousers or down with a pullover and sweatpants—it looks good with (literally) anything.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 59, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/816dde1b_0322.jpg?v=1753411459&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/16e28db9_9738.jpg?v=1753411460&width=900')
