INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('b28fc9ec-ea89-4f86-a955-f2a5c8b2a7ac', '20000000-0000-0000-0000-000000000007', 'Giày Bệt & Loafer Da Mềm Day Loafer — Đen', 3230000, 'Giày Bệt & Loafer Da Mềm Day Loafer — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The Day Loafer is a modern take on a traditional smoking loafer. Featuring a square toe in our ultra soft, Nappa leather with a comfortable back for easy slip-on and, our signature cushioned insole for all day wearability. The best part? You can loaf around in suede too.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 230, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/e864bbee_d112.jpg?v=1753411527&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2e165dec_a36e.jpg?v=1753411528&width=900')
