INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('e88348dd-9bb2-495d-ac38-59fa6d4ba258', '20000000-0000-0000-0000-000000000007', 'Giày Sneaker Năng Động Day Sneaker — Trắng kem', 3350000, 'Giày Sneaker Năng Động Day Sneaker — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The Day Sneaker features a slightly tapered toe, a classic lace-up design, a versatile low-ankle height, and a contrast rubber outsole for durability in new colors. Easy to dress up with our Everlane Editions collections or dress down with our signature Way-High® denim. This shoe showcases a rubber outsole made of a natural and recycled rubber blend that’s 94.2% free of virgin plastic, and 100% recycled polyester laces and linings. This leather is sourced from a Leather Working Group Gold-certified tannery. The Leather Working Group (LWG) Audit Standards provide transparency and accountability within the leather supply chain—covering energy and water usage, safe chemical practices, worker health and safety, and wastewater management.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 249, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/f5eb7274_3d4f.jpg?v=1753411587&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/a54a2df5_3d04.jpg?v=1753411587&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
