INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('372d53ff-a0b3-4fc6-adde-d9f9801690a8', '20000000-0000-0000-0000-000000000007', 'Giày Sneaker Năng Động Tread-Bare Sneaker — Trắng kem', 4190000, 'Giày Sneaker Năng Động Tread-Bare Sneaker — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Its lightweight design is made from recycled cotton canvas with a 100% natural latex rubber outsole and recycled trims. The best part? It is our lowest carbon-impact sneaker ever—producing only 4.78 kg CO₂e per pair (that’s less than a single cheeseburger or a reuseable water bottle). With its barely there feel, you’ll forget you’re wearing shoes. Want to learn more about how we calculated the impact of this shoe? Click here .', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 28, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/68a3c5cf_9e5e.jpg?v=1753411590&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/3f8d4dfb_4d01.jpg?v=1753411589&width=900')
