INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('38976d92-32ab-4d0f-af10-45f001d0a786', '20000000-0000-0000-0000-000000000007', 'Giày Bệt & Loafer Da Mềm Day Mule — Đen', 3710000, 'Giày Bệt & Loafer Da Mềm Day Mule — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Made with incredibly soft Nappa leather, the Leather Day Mule features a tapered, square-shaped toe with our classic inset, circular-shaped heel. They feel just as good as they look. This mule uses leather sourced from a tannery rated Gold by the Leather Working Group (LWG)—the highest rating a tannery can receive for demonstrating best practices in environmental compliance and performance capabilities.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 130, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/a54a7caf_d288.jpg?v=1753411686&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/7f579c9f_733c.jpg?v=1753411686&width=900')
