INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('f1feb55d-d872-4279-ac19-800984beafb0', '20000000-0000-0000-0000-000000000007', 'Giày Boots Cổ Thấp Puffa Boot — Đen', 3710000, 'Giày Boots Cổ Thấp Puffa Boot — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. You loved our Puffa Clog so much, we made it in boot form. With the same height and playful shape, this leather Chelsea style features elastic at the sides for pull-on ease and comfort that feels so good, you won’t want to take it off. Talk about fashion and function. This boot uses leather sourced from a tannery rated Gold by the Leather Working Group (LWG)—the highest rating a tannery can receive for demonstrating best practices in environmental compliance and performance capabilities.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 168, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/1c39d9fb_88fa.jpg?v=1753411623&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/a7400787_7504.jpg?v=1753411623&width=900')
