INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('653e3646-5860-48f3-a965-fff0f0257c20', '20000000-0000-0000-0000-000000000007', 'Giày Puffa Clog — Đen', 4190000, 'Giày Puffa Clog — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The Puffa Clog is the newest addition to leather our mule family. Featuring a leather covered platform wedge and rubber outsole, the wedge is covered with padding—perfect for all-day wearability. The leather for this shoe is sourced from a Leather Working Group Gold-certified tannery. The Leather Working Group (LWG) Audit Standards provide transparency and accountability within the leather supply chain—covering energy and water usage, safe chemical practices, worker health and safety, and wastewater management.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 194, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/006f10e0_07c1.jpg?v=1753411591&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/5de6e6e5_a5b7.jpg?v=1753411591&width=900')
