INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('dc447223-3ff2-4b70-a6a9-789b2b55d332', '20000000-0000-0000-0000-000000000007', 'Giày Boots Cổ Thấp Rain Boot — Vàng bơ', 2990000, 'Giày Boots Cổ Thấp Rain Boot — Vàng bơ với sắc vàng bơ tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The Rain Boot features a versatile ankle height, a slip-resistant tread, and a custom-designed cushioned insole for walkable comfort. Plus, stretch side panels and pull tabs make it easy to slide on and go. Even better? It’s made from flexible, easy-to-clean rubber and was designed to leave plenty of room for thick, comfy socks, so you can stay warm no matter the weather.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 30, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/65e7901c_62cf.jpg?v=1753411548&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/bd3ed312_b9eb.jpg?v=1753411548&width=900')
