INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('8890f29c-48b3-437a-a208-a295ab7729cb', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công ReNew Transit Backpack — Nâu Caramel', 2810000, 'Túi Da Thủ Công ReNew Transit Backpack — Nâu Caramel với sắc nâu caramel tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The ReNew 15" Transit Backpack features a 15" exterior laptop pocket for easy TSA access, catch-all zip pockets for passports and tickets, interior slip pockets for magazines and notebooks, one interior and one exterior water bottle holder, a handy magnetic closure, and a pass-through strap that attaches to rolling luggage. Oh, and it’s made using 100% recycled polyester from recycled plastic bottles.* *The zipper sliders and some of the pulls are metal, but other zipper pulls are recycled polyester. The only new plastic is for the zipper coil (teeth), which is not made from recycled material—yet. We’ve eliminated 90% of the virgin plastic from our supply chain. Learn about what we’ve done—and the challenges ahead—on our Sustainability page.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 49, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/0d817063_5256.jpg?v=1753411429&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/377993de_06ec.jpg?v=1753411429&width=900')
ON CONFLICT (product_id) DO UPDATE SET
  image_url = EXCLUDED.image_url,
  image_alt_url = EXCLUDED.image_alt_url,
  base_price = EXCLUDED.base_price,
  description = EXCLUDED.description;


