INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('0a72b3ce-3650-434e-a4d2-3a497f83bebd', '20000000-0000-0000-0000-000000000005', 'Phụ kiện ReNew Transit Weekender — Đen', 1370000, 'Phụ kiện ReNew Transit Weekender — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The ReNew Transit Weekender is fully featured—padded laptop sleeve, two water bottle holders, exterior zip pocket, luggage handle pass-through (that''s also a pocket), and multiple ways to carry: crossbody, shoulder, or in-hand. Oh, and it’s made using 100% recycled polyester from recycled plastic bottles.* *The zipper sliders and some of the pulls are metal, but other zipper pulls are recycled polyester. The only new plastic is for the zipper coil (teeth), which is not made from recycled material—yet. We’ve eliminated 90% of the virgin plastic from our supply chain. Learn about what we’ve done—and the challenges ahead—on our Sustainability page.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 87, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/7e3727cd_c164.jpg?v=1753411442&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/1ae8296e_de07.jpg?v=1753411442&width=900')
