INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('9625e630-31d3-4b7c-a9cc-6c9dca374a25', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Recycled Nylon Camera Bag — Đen', 1130000, 'Túi Da Thủ Công Recycled Nylon Camera Bag — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Our new, small camera crossbody features an adjustable shoulder strap with two main zippered compartments, and one front exterior slip pocket. The main body material and all webbing is made from 100% GRS-certified recycled nylon*. Lining is made from 100% recycled polyester. With the goal of increasing the use of recycled materials and reducing the harmful impacts of production, the Global Recycled Standard (GRS) sets requirements for third-party certification of recycled input in products—including chain of custody, social and environmental practices, and chemical restrictions. *Zipper tape is recycled, but we’re still working on sourcing the zipper teeth from recycled materials!', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 125, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/719ecb06_e0cf.jpg?v=1753411636&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/bcd4f539_a627.jpg?v=1753411636&width=900')
