INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('0b2f9b93-c932-413b-a060-5a0c765212d7', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Recycled Nylon Crossbody — Đen', 3290000, 'Túi Da Thủ Công Recycled Nylon Crossbody — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. This small, barrel-shaped crossbody features an adjustable shoulder strap, plus shorter handles for versatile toting. It has one main zippered compartment with two internal slip pockets on the side, and one front external zippered pocket. The main body material and all webbing is made from 100% GRS-certified recycled nylon*. Lining is made from 100% recycled polyester. With the goal of increasing the use of recycled materials and reducing the harmful impacts of production, the Global Recycled Standard (GRS) sets requirements for third-party certification of recycled input in products—including chain of custody, social and environmental practices, and chemical restrictions. *Zipper tape is recycled, but we’re still working on sourcing the zipper teeth from recycled materials!', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 163, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/c5c7dadb_5d7d.jpg?v=1753411633&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/3bd42d42_fd71.jpg?v=1753411633&width=900')
