INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('2312828a-0244-4c47-a13b-2eb7ef381314', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Luxe Italian Leather Tote — Đen', 2930000, 'Túi Da Thủ Công Luxe Italian Leather Tote — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The Luxe Italian Leather Tote is our largest (hello roomiest) tote yet. Featuring two over-the-shoulder straps, an interior slip pocket—to cradle your phone, keys, chapstick, etc. and a leather covered metal snap button closure. This spacious, sturdy bag can hold 15” laptops, plus all your daily essentials without losing its shape.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 182, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/6fb7e07e_f5a6.jpg?v=1753411537&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/15fde6bd_e852.jpg?v=1753411537&width=900')
