INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('47d692b4-e588-4a91-a0c5-972c00136212', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Cactus Leather Sling Bag — Xám đá', 890000, 'Túi Da Thủ Công Cactus Leather Sling Bag — Xám đá với sắc xám đá tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. No pesticides. Nopales. In collaboration with Desserto®, we took our best-selling sling bag and remade it with organically sourced prickly pear cactus. The Desserto® textile is our first plant-based material to be used as a leather alternative. Why cactus? It has a great CO2 sequestering capacity and acts like a natural carbon sink, while using zero irrigation and naturally regenerating soil. Plus, 50% of the byproduct is used to feed cattle. It’s a cruelty-free, sustainable material without any of the toxic chemicals, phthalates, and PVC that conventional leather has.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 201, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/216fbf74_391e.jpg?v=1753411393&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/826db1ae_9a00.jpg?v=1753411393&width=900')
