INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('0cc25a0a-ab6b-47f2-a70a-cc7d68568737', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Luxe Medium Italian Leather Tote — Đen', 3170000, 'Túi Da Thủ Công Luxe Medium Italian Leather Tote — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. New to our tote family, meet the medium size of our Luxe Italian Leather Tote. Easy to wear with effortless over-the-shoulder straps, it has a spacious interior with an internal slip pocket at the back of the bag for all your quick-reach essentials, and fastens with a leather-covered snap button. The perfect size to fit all your work/life staples, this sleek, chic Italian leather tote adds a little look of luxe to your day to day.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 220, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/811a98d7_a0f2.jpg?v=1753411539&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/f9161f59_57e0.jpg?v=1753411540&width=900')
