INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('12a785bb-89c8-4da0-aa4a-5d3449663d0c', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Recycled Nylon Tote — Đen', 1370000, 'Túi Da Thủ Công Recycled Nylon Tote — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. This medium-sized tote features over-the-shoulder straps, plus shorter handles for versatile toting. There is one main zippered compartment with one small internal zippered pocket, and one front exterior slip pocket, plus a padded bottom. Fits 13" laptop. The main body material and all webbing is made from 100% GRS-certified recycled nylon*. Lining is made from 100% recycled polyester. With the goal of increasing the use of recycled materials and reducing the harmful impacts of production, the Global Recycled Standard (GRS) sets requirements for third-party certification of recycled input in products—including chain of custody, social and environmental practices, and chemical restrictions. *Zipper tape is recycled, but we’re still working on sourcing the zipper teeth from recycled materials!', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 239, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/431d7e2a_389b.jpg?v=1753411640&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/6db2bff9_869d.jpg?v=1753411640&width=900')
