INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('e5da967d-1b2c-403b-aae4-ed1382d83fa6', '20000000-0000-0000-0000-000000000005', 'Phụ kiện ReNew Transit Catch-All Case — Xám đá', 1250000, 'Phụ kiện ReNew Transit Catch-All Case — Xám đá với sắc xám đá tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The ReNew Transit Catch-All Case features five interior drop-in pockets and one exterior zip pocket, which makes it perfect for organizing toiletries (and other small things). Even better? It’s designed to snap down for compact travel or roll back for easy access. Oh, and it’s made using 100% recycled polyester from recycled plastic bottles.* *The zipper sliders and pullers are made from both metal and recycled polyester. The only new plastic used is for the zipper coil (teeth), which is not made from recycled material—yet.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 258, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/dfa8f4d3_ef2a.jpg?v=1753411635&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/c021ca2b_52c8.jpg?v=1753411635&width=900')
