INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('a3475f12-d852-4b74-ade4-867e9b6cff31', '20000000-0000-0000-0000-000000000005', 'Phụ kiện Cactus Leather Hobo — Đen', 1130000, 'Phụ kiện Cactus Leather Hobo — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. It features an adjustable strap (for an easy, over-the-shoulder look), an inside pocket, and a spacious interior for your basic essentials. Made from organically sourced prickly pear cactus, the Desserto® textile is our first plant-based material to be used as a leather alternative. Why cactus? It has a great CO2 sequestering capacity, acts like a natural carbon sink, uses zero irrigation, and naturally regenerates soil. Plus, 50% of the byproduct is redirected to the food industry and used to feed cattle.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 37, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/b929591b_f546.jpg?v=1750093749&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/da19ecf1_8689.jpg?v=1750093749&width=900')
