INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('4355d473-0c60-4848-a000-754c9be3396b', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Luxe Italian Leather Crossbody — Nâu Caramel', 1490000, 'Túi Da Thủ Công Luxe Italian Leather Crossbody — Nâu Caramel với sắc nâu caramel tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Meet the smallest addition to our Luxe Italian Leather Tote family. The Luxe Italian Leather Crossbody is a classic tote silhouette made mini, with an adjustable cross-body strap. Like our larger totes, it features a leather-covered metal snap button closure for the main opening, and a neat interior pocket for your easy-to-grab essentials. And, it’s made with luxe Italian leather for a little pop of polish to your daily look. The leather in this bag is sourced from a tannery rated Silver by the Leather Working Group (LWG). Gold and Silver are the highest ratings a tannery can receive for demonstrating best practices in environmental compliance and performance capabilities.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 56, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/26eeea05_a898.jpg?v=1753411566&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/af980e9d_579a.jpg?v=1753411566&width=900')
