INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('5b879881-be65-4f8e-a641-9facb4564ef6', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Cactus Triangle Tote — Đen', 1370000, 'Túi Da Thủ Công Cactus Triangle Tote — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. No pesticides. Nopales. Made from organic prickly pear, the Cactus Triangle Tote is as soft and durable as leather—–with a lower environmental footprint on the planet compared to traditional virgin leather. Featuring an interior slip pocket, it has plenty of room for your everyday essentials and then some. Made from organically sourced prickly pear cactus, the Desserto® textile is our first plant-based material to be used as a leather alternative. Why cactus? It has a great CO2 sequestering capacity, acts like a natural carbon sink, uses zero irrigation, and naturally regenerates soil. Plus, 50% of the byproduct is redirected to the food industry and used to feed cattle.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 75, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/1cfac78d_fc70.jpg?v=1750093801&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/9b8dc75d_eb03.jpg?v=1750093802&width=900')
