INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('3a94319b-67bd-45e9-a768-6710c477180b', '20000000-0000-0000-0000-000000000005', 'Phụ Kiện Phối Đồ Organic Cotton No-Show Sock 3-Pack — Trắng kem', 3170000, 'Phụ Kiện Phối Đồ Organic Cotton No-Show Sock 3-Pack — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. The Organic Cotton No-Show Sock 3-Pack is sneaker and bootie ready. Made of super-soft organic cotton (hence the name) it features silicone pads at the heels to ensure you won’t get caught slipping. Once they’re on, no one will ever know if you’re wearing socks—ta-da, magic. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 158, 4.5, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2983b24c_16a6.jpg?v=1753411582&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/5ddd37e5_2e0b.jpg?v=1753411582&width=900')
