INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('ee32ce46-2830-452f-aa0f-d34ac7732bb6', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Organic Canvas Pouch — Trắng kem', 3050000, 'Túi Da Thủ Công Organic Canvas Pouch — Trắng kem với sắc trắng kem tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Keep all your essentials safely tucked away while also ensuring your bag stays organized with The Organic Canvas Pouch. Made with 100% organic cotton canvas, it features a metal zipper to keep things securely in place. Perfect for keeping all your can’t-leave-home-withouts in one handy place. Organic cotton uses crop rotation, cover crops, and organic fertilizers instead of toxic chemical fertilizers or pesticides—which means cleaner water, lower water usage, lower pesticide use, healthier soil, and a safer working environment for cotton farmers, compared to conventional cotton.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 51, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/1f141ce9_5b25.jpg?v=1753411570&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/5faf02e0_a2b7.jpg?v=1753411570&width=900')
