INSERT INTO products (product_id, category_id, name, base_price, description, status, shop_id, approval_status, sold_count, rating, image_url, image_alt_url)
VALUES ('522dde64-a287-4b7b-a4ab-ca97c30a06e4', '20000000-0000-0000-0000-000000000005', 'Túi Da Thủ Công Cactus Leather Mini Sling Bag — Đen', 1850000, 'Túi Da Thủ Công Cactus Leather Mini Sling Bag — Đen với sắc đen tinh tế, đường cắt chuẩn xác dễ dàng phối nhiều lớp (layering) trong tủ đồ tối giản hiện đại. Featuring slip pockets perfect for your phone and cards, with an adjustable strap, the Cactus Leather Mini Sling Bag is fit for all of your essentials. Oh, and it’s made from organically sourced prickly pear cactus. The Desserto® textile is our first plant-based material to be used as a leather alternative. Why cactus? It has a great CO2 sequestering capacity, acts like a natural carbon sink, uses zero irrigation, and naturally regenerates soil. Plus, 50% of the byproduct is redirected to the food industry and used to feed cattle.', 'active', 'fe2c137e-8365-42d7-9506-5ae1acfaf0be', 'published', 89, 4.7, 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2a3fc164_8768.jpg?v=1753411394&width=900', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/4051c09a_3cee.jpg?v=1753411394&width=900')
